}

variable "aws_region" {
  description = "AWS region where the ECR repository and IAM role will be created."
  type        = string
  default     = "us-east-1"
}

variable "ecr_repository_name" {
  description = "Name of the Amazon ECR repository for the ReactJS application."
  type        = string
  default     = "reactjs-app-repo"
}

variable "ecs_task_execution_role_name" {
  description = "Name of the IAM role used by ECS tasks for task execution."
  type        = string
  default     = "ecsTaskExecutionRole"
}

resource "aws_ecr_repository" "reactjs_app_repo" {
  name                 = var.ecr_repository_name
  image_tag_mutability = "IMMUTABLE"

  image_scanning_configuration {
    scan_on_push = true
  }

  tags = {
    Name        = var.ecr_repository_name
    Application = "reactjs-app"
  }
}

resource "aws_iam_role" "ecs_task_execution_role" {
  name = var.ecs_task_execution_role_name

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ecs-tasks.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = {
    Name = var.ecs_task_execution_role_name
  }
}

resource "aws_iam_role_policy_attachment" "ecs_task_execution_role_policy_attachment" {
  role       = aws_iam_role.ecs_task_execution_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonECSTaskExecutionRolePolicy"
}

output "ecr_repository_url" {
  description = "URL of the created ECR repository."
  value       = aws_ecr_repository.reactjs_app_repo.repository_url
}

output "ecs_task_execution_role_arn" {
  description = "ARN of the created ECS task execution IAM role."
  value       = aws_iam_role.ecs_task_execution_role.arn
}

